/** Reproducible finite synthetic producer contract load, explicitly separate from full autonomous MAS throughput. */
class VerificationLoadScenarioTest {
    record Workload(int agents,int artifacts,int properties,int contexts,int goals,int invariants,int warmup,int measured){}
    record Fixture(ModelSnapshot source,CslMonitorConfiguration config,List<RuntimeFact> facts,List<BridgeEntityId> artifacts){}
    record Measurement(boolean cached,long setupNanos,Map<String,Object> distribution,Map<String,Object> phases,long journalBytes,long replayBytes,long heapDelta,long gcCollections,List<String> logicalHashes,String finalStateHash,String finalResultHash){}
    static final String CACHE="use.jacamo.semantics.disableBindingCache";
    static RuntimeFact fact(BridgeEntityId id,RuntimeFactKind kind,Map<String,Object> values){return new RuntimeFact(id,kind,values,List.of(),ProjectionStatus.MATERIALIZED_FAITHFULLY,Completeness.COMPLETE,List.of());}
    static BridgeEntityId actor(int i){return new BridgeEntityId("cartago","environment","agent","/main","benchAgent"+i,Integer.toString(i));}
    static BridgeEntityId group(int i){return new BridgeEntityId("moise","organisation","group-board","org","group"+i,"run:group-uuid-"+i);}
    static Fixture fixture(Workload w)throws Exception {return fixture(w,VerificationLoadArtifact.class);}
    static Fixture fixture(Workload w,Class<? extends cartago.Artifact> artifactClass)throws Exception {
        var dir=Files.createTempDirectory(Path.of("target"),"load-input-");Files.createDirectories(dir.resolve("src/agt"));Files.createDirectories(dir.resolve("src/org"));Files.copy(Path.of("src/test/resources/semantics/profile-v1/src/agt/a.asl"),dir.resolve("src/agt/a.asl"));Files.copy(Path.of("src/test/resources/semantics/profile-v1/src/org/monitor.xml"),dir.resolve("src/org/monitor.xml"));Files.writeString(dir.resolve("monitor.jcm"),Files.readString(Path.of("src/test/resources/semantics/profile-v1/monitor.jcm")).replace(CslCounterArtifact.class.getName(),artifactClass.getName()));var path=dir.resolve("monitor.jcm").toAbsolutePath();var source=new OfficialProjectAdapter().adapt(new OfficialProjectLoader().load(path),path);var org=source.semanticContract().moiseOrganizations().getFirst();var groupDef=org.structuralSpecification().groups().getFirst();var roleDef=org.structuralSpecification().roles().stream().filter(r->r.roleId().equals("worker")).findFirst().orElseThrow();
        var attrs=new ArrayList<CslSchema.Attribute>();for(int i=0;i<w.properties();i++)attrs.add(new CslSchema.Attribute("p"+i,"p"+i,"Integer","p"+i,false));var domain=new CslSchema.Classifier("domain",DomainProjection.artifactId(artifactClass.getName()),"LoadEntity",CslSchema.Kind.ENTITY,"",false,attrs);var base=new OrganizationalMappingRules().derive(source,List.of(domain),List.of(),List.of(),List.of(),new RequirementModel(List.of()));var role=base.schema().classifiers().stream().filter(c->c.sourceId().equals(roleDef.metadata().semanticId())).findFirst().orElseThrow();
        var facts=new ArrayList<RuntimeFact>();var workspace=new TreeMap<String,Object>();workspace.put("normalizedEventKind","UPSERT_CARTAGO_WORKSPACE");workspace.put("semanticId","benchmark:/main");workspace.put("name","main");workspace.put("fullName","/main");workspace.put("uuid","benchmark-ws");workspace.put("environmentId","benchmark");workspace.put("environmentName","benchmark");workspace.put("environmentVersion","3.1");workspace.put("environmentSemanticId","benchmark:environment");workspace.put("defaultInfrastructureLayer","");workspace.put("parentSemanticId","");workspace.put("local",true);workspace.put("protocol","");workspace.put("remotePath","");workspace.put("address","");facts.add(fact(new BridgeEntityId("cartago","environment","workspace","benchmark","/main","benchmark-ws"),RuntimeFactKind.WORKSPACE,workspace));for(int i=0;i<w.agents();i++)facts.add(fact(actor(i),RuntimeFactKind.AGENT,Map.of("normalizedEventKind","UPSERT_CARTAGO_AGENT_IDENTITY","semanticId",actor(i).canonical(),"name","agent"+i,"globalId","benchAgent"+i,"localId",i,"workspaceSemanticId","benchmark:/main")));
        var ids=new ArrayList<BridgeEntityId>();for(int i=0;i<w.artifacts();i++){var id=new BridgeEntityId("cartago","environment","artifact","/main","x"+i,"uuid-"+i);ids.add(id);var data=new TreeMap<String,Object>();data.put("normalizedEventKind","UPSERT_CARTAGO_ARTIFACT");data.put("semanticId",id.canonical());data.put("name","x"+i);data.put("uuid",id.incarnation());data.put("artifactTypeSemanticId",domain.sourceId());data.put("artifactTypeJavaClassName",artifactClass.getName());data.put("creatorAgentSemanticId","");data.put("workspaceSemanticId","benchmark:/main");data.put("properties",properties(id,w.properties(),0));facts.add(fact(id,RuntimeFactKind.ARTIFACT,data));for(var property:properties(id,w.properties(),0))facts.add(fact(new BridgeEntityId("cartago","environment","observable-property-snapshot",id.canonical(),(String)property.get("propertyId"),"snapshot"),RuntimeFactKind.PROPERTY,property));}
        for(int i=0;i<w.contexts();i++)facts.add(fact(group(i),RuntimeFactKind.GROUP_BOARD,Map.of("normalizedEventKind","UPSERT_MOISE_GROUP","semanticId",group(i).canonical(),"runtimeIdentity",group(i).canonical(),"name","group"+i,"organisationName","org","organisationSpecSemanticId",org.metadata().semanticId(),"groupSpecSemanticId",groupDef.metadata().semanticId(),"boardArtifactIdentity","group-uuid-"+i,"organisationDefinition",SemanticJson.tree(org),"players",List.of(Map.of("agentSemanticId",actor(i%w.agents()).canonical(),"roleSemanticId",roleDef.metadata().semanticId())))));
        var requirements=new ArrayList<RequirementModel.Node>();for(int i=0;i<w.goals();i++){int c=i%w.contexts();var binding=new RequirementModel.Binding("actor"+c,actor(c%w.agents()).canonical(),role.id(),group(c).canonical(),ids.get(i%ids.size()).canonical(),"domain","episode"+i);requirements.add(new RequirementModel.Node("goal"+i,"requirement"+i,RequirementModel.Kind.GOAL,RequirementModel.Temporal.values()[i%4],binding,"self.p0 >= 0 and LoadEntity.allInstances()->size() = "+w.artifacts(),"true",RequirementModel.Refinement.NONE,List.of(),"",""));}
        var invariants=new ArrayList<CslSchema.Invariant>();for(int i=0;i<w.invariants();i++)invariants.add(new CslSchema.Invariant("inv"+i,"domain","Nonnegative"+i,"self.p0 >= 0 and LoadEntity.allInstances()->forAll(x | x.p0 >= -1)"));var schema=new CslSchema(base.schema().id(),base.schema().classifiers(),base.schema().associations(),invariants,List.of(),base.schema().policy());var config=new CslMonitorConfiguration(base.version(),base.profile(),schema,new RequirementModel(requirements),base.decisions());return new Fixture(source,config,List.copyOf(facts),List.copyOf(ids));
    }
    static List<Map<String,Object>> properties(BridgeEntityId artifact,int count,int value){var properties=new ArrayList<Map<String,Object>>();for(int i=0;i<count;i++)properties.add(Map.of("normalizedEventKind","UPSERT_CARTAGO_PROPERTY_SNAPSHOT","semanticId",artifact.canonical()+":property:p"+i,"artifactSemanticId",artifact.canonical(),"propertyId","p"+i,"name","p"+i,"values",List.of(Integer.toString(i==0?value:0)),"valueTypes",List.of("java.lang.Integer")));return List.copyOf(properties);}
    static RuntimeSnapshot snapshot(Fixture f){var watermarks=Map.of("cartago",new SourceWatermark("cartago",0),"moise:org",new SourceWatermark("moise:org",0));return new RuntimeSnapshot("benchmark-initial",f.source().modelRevision(),Instant.EPOCH,Instant.EPOCH,watermarks,watermarks,1,f.facts(),Map.of("cartago",Completeness.COMPLETE,"moise:org",Completeness.PARTIAL),"synthetic-selected-boundary",Map.of("scope","SYNTHETIC_ADAPTER_CONTRACT_NOT_FULL_LIVE_MAS"));}
    static RuntimeEvent delta(Fixture f,String stream,long sequence,int index,int value){var id=f.artifacts().get(index);return new RuntimeEvent(stream+":"+sequence,"benchmark",1,f.source().modelRevision(),"cartago",stream,sequence,Instant.EPOCH,RuntimeEventKind.CHANGED,RuntimeFactKind.ARTIFACT,ProjectionStatus.MATERIALIZED_FAITHFULLY,id,null,"","",Map.of(),Map.of("normalizedEventKind","APPLY_CARTAGO_PROPERTY_DELTA","semanticId",id.canonical(),"removedPropertySemanticIds",List.of(),"properties",properties(id,1,value)),new SourceWatermark(stream,sequence),Completeness.COMPLETE,List.of());}
    static Measurement run(Fixture f,Workload w,boolean cached)throws Exception {
        System.setProperty(CACHE,Boolean.toString(!cached));long heap=used(),gc=collections(),setup=System.nanoTime();var built=new CodeGroundedNativePipeline().build(f.source(),NativeProjectionMode.AUTO,f.config());setup=System.nanoTime()-setup;var output=Files.createTempDirectory(Path.of("target"),"benchmark-replay-");
        try(var projector=new NativeRuntimeProjector(built,"benchmark",1,f.source().modelRevision())) {
            projector.applySnapshot(snapshot(f));assertEquals(w.agents(),projector.system().state().objectsOfClass(projector.system().model().getClass("AtomicAgent")).size());assertEquals(w.artifacts(),projector.system().state().objectsOfClass(projector.system().model().getClass("LoadEntity")).size());assertEquals(w.goals(),projector.coordinator().latest().semantic().requirements().size());assertTrue(projector.coordinator().latest().semantic().requirements().values().stream().allMatch(m->m.raw()==IntentionalMarking.Status.SATISFIED),projector.coordinator().latest().semantic().requirements().toString());
            var durations=new long[w.measured()];var hashes=new ArrayList<String>();for(int i=0;i<w.warmup()+w.measured();i++){long t=System.nanoTime();projector.apply(delta(f,"cartago",i+1,i%w.artifacts(),i%4==2?-1:i%4));long elapsed=System.nanoTime()-t;var result=projector.coordinator().lastObservation();assertEquals("CURRENT_OBSERVED",result.freshness(),result.diagnostic());assertEquals(w.goals(),result.semantic().requirements().size());assertTrue(result.semantic().requirements().values().stream().noneMatch(m->m.raw()==IntentionalMarking.Status.UNDETERMINED),result.semantic().requirements().toString());assertEquals(Integer.toString(i%4==2?-1:i%4),projector.mutations().objectForSemanticId(f.artifacts().get(i%w.artifacts()).canonical()).state(projector.system().state()).attributeValue("p0").toString());hashes.add(result.resultHash());if(i>=w.warmup())durations[i-w.warmup()]=elapsed;}
            var end=projector.coordinator().lastObservation();var replay=new NativeRuntimeReplay();replay.exportBundle(projector,built.export().useText(),output);var report=replay.replay(output);assertTrue(report.complete(),report.diagnostics().toString());assertEquals(end.stateHash(),report.finalStateHash());assertEquals(end.resultHash(),report.finalResultHash());long size;try(var files=Files.list(output)){size=files.filter(Files::isRegularFile).mapToLong(p->{try{return Files.size(p);}catch(Exception e){throw new IllegalStateException(e);}}).sum();}
            var phases=projector.coordinator().performanceMetrics();assertTrue(((Number)phases.get("retainedSerializedBytes")).longValue()<=64L*1024*1024,phases.toString());return new Measurement(cached,setup,distribution(durations),phases,Files.size(projector.coordinator().journal().path()),size,used()-heap,collections()-gc,hashes,end.stateHash(),end.resultHash());
        }
    }
    static Map<String,Object> distribution(long[] ns){var sorted=ns.clone();Arrays.sort(sorted);long sum=Arrays.stream(sorted).sum();return Map.of("samples",ns.length,"p50Nanos",sorted[(int)Math.ceil(.50*ns.length)-1],"p95Nanos",sorted[(int)Math.ceil(.95*ns.length)-1],"p99Nanos",sorted[(int)Math.ceil(.99*ns.length)-1],"maxNanos",sorted[sorted.length-1],"acceptedBoundariesPerSecond",1_000_000_000.0*ns.length/Math.max(1,sum));}
    static long used(){var r=Runtime.getRuntime();return r.totalMemory()-r.freeMemory();}static long collections(){return java.lang.management.ManagementFactory.getGarbageCollectorMXBeans().stream().mapToLong(b->Math.max(0,b.getCollectionCount())).sum();}
    @Test void boundedLoadMatrixKeepsFullEvaluationAndReplayHashesIdenticalWithAndWithoutBindingCache()throws Exception {
        String old=System.getProperty(CACHE);var runs=new ArrayList<Object>();try {for(var workload:List.of(new Workload(1,1,1,1,1,1,4,16),new Workload(10,10,10,10,10,10,4,12),new Workload(50,100,10,10,100,10,2,6),new Workload(50,10,10,10,1000,1,0,2))) {
            var fixture=fixture(workload);var baseline=run(fixture,workload,false);var cached=run(fixture,workload,true);assertEquals(baseline.logicalHashes(),cached.logicalHashes());assertEquals(baseline.finalStateHash(),cached.finalStateHash());runs.add(Map.of("workload",SemanticJson.tree(workload),"sourceRevision",fixture.source().modelRevision(),"configurationHash",SemanticJson.hash(CanonicalJson.decode(fixture.config().bytes())),"baseline",SemanticJson.tree(baseline),"cached",SemanticJson.tree(cached)));}
            var manifest=new TreeMap<String,Object>();manifest.put("version","1.0");manifest.put("scope","SYNTHETIC_ADAPTER_BOUNDARY_SELECTED_SCALAR_AND_ENACTMENT_OBSERVATIONS_NOT_FULL_LIVE_MAS_THROUGHPUT");manifest.put("jvm",System.getProperty("java.runtime.version"));manifest.put("os",System.getProperty("os.name")+" "+System.getProperty("os.arch"));manifest.put("processors",Runtime.getRuntime().availableProcessors());manifest.put("maxHeap",Runtime.getRuntime().maxMemory());manifest.put("gc",java.lang.management.ManagementFactory.getGarbageCollectorMXBeans().stream().map(java.lang.management.MemoryManagerMXBean::getName).toList());manifest.put("seed",0);manifest.put("runs",runs);manifest.put("policy","Full OCL and all requirements reevaluated at every boundary; no event coalescing or incremental selection");manifest.put("limits",List.of("Finite event-count workload, unpaced maximum throughput","No Java interpreter/cycle scheduling or observer capture latency measurement","Heap delta includes GC; not retained-heap proof","Percentiles from finite measured sample set; no SLA"));Files.write(Path.of("target/semantic-performance.json"),CanonicalJson.encode(manifest));
        }finally{if(old==null)System.clearProperty(CACHE);else System.setProperty(CACHE,old);}
    }
    @Test void twoSourceWritersAreSerializedWithoutDroppingSharedStateUpdatesAndReplayRetainsAcceptedOrder()throws Exception {
        var workload=new Workload(2,1,1,2,4,1,0,1);var f=fixture(workload);var built=new CodeGroundedNativePipeline().build(f.source(),NativeProjectionMode.AUTO,f.config());try(var projector=new NativeRuntimeProjector(built,"benchmark",1,f.source().modelRevision())){projector.applySnapshot(snapshot(f));var pool=java.util.concurrent.Executors.newFixedThreadPool(2);var barrier=new java.util.concurrent.CountDownLatch(1);try{var a=pool.submit(()->{barrier.await();for(int i=1;i<=10;i++)projector.apply(delta(f,"bench-A",i,0,i%2));return null;});var b=pool.submit(()->{barrier.await();for(int i=1;i<=10;i++)projector.apply(delta(f,"bench-B",i,0,i%2-1));return null;});barrier.countDown();a.get(30,java.util.concurrent.TimeUnit.SECONDS);b.get(30,java.util.concurrent.TimeUnit.SECONDS);}finally{pool.shutdownNow();assertTrue(pool.awaitTermination(5,java.util.concurrent.TimeUnit.SECONDS));}assertEquals(22,projector.coordinator().journal().persistedEntries());assertFalse(projector.coordinator().journal().hasGap());var output=Files.createTempDirectory(Path.of("target"),"concurrent-replay-");new NativeRuntimeReplay().exportBundle(projector,built.export().useText(),output);var replay=new NativeRuntimeReplay().replay(output);assertTrue(replay.complete(),replay.diagnostics().toString());assertEquals(projector.coordinator().lastObservation().resultHash(),replay.finalResultHash());assertTrue(projector.coordinator().highWatermark()>=1);}
    }
}
